// [Lưu ý]: Học viên tự khai báo thư viện cần thiết

class SinhVien {
private:
    std::string ten;

public:
    SinhVien(const std::string& t) : ten(t) {}

    // Hàm bạn để chuẩn hóa tên
    friend void chuanHoaTen(SinhVien& sv);

    void inTen() const {
        std::cout << ten << std::endl;
    }
};

// Định nghĩa hàm bạn
void chuanHoaTen(SinhVien& sv) {
    // Chuyển đổi tất cả chữ cái sang chữ thường
    for (char& c : sv.ten) {
        c = tolower(c);
    }

    // Hoàn thiện phần tử đầu tiên thành chữ hoa
    if (!sv.ten.empty()) {
        sv.ten[0] = toupper(sv.ten[0]);

        // Nếu có nhiều từ, chỉ giữ chữ hoa cho mỗi từ đầu tiên
        size_t pos = 1;
        while ((pos = sv.ten.find(' ', pos)) != std::string::npos) {
            ++pos;
            if (pos < sv.ten.size()) {
                sv.ten[pos] = toupper(sv.ten[pos]);
            }
        }
    }
}

