    vector<double> diemSo;
    vector<int> tronGo;
public:
    void ThemMon(double diem, int trongSo);
    double TinhGPA();
};
```

### Bước 2: Phương thức `ThemMon()`
Phương thức này dùng để thêm một cặp điểm số và trọng số vào danh sách.

```cpp
void SinhVien::ThemMon(double diem, int tronSo) {
    diemSo.push_back(diem);
    tronGo.push_back(tronSo);
}
```

### Bước 3: Phương thức `TinhGPA()`
Phương thức này sẽ sử dụng dữ liệu đã lưu trữ trong vectors để tính GPA.

```cpp
double SinhVien::TinhGPA() {
    if (diemSo.empty()) return 0.0;

    double tongDiemTrongTrungBinh = 0.0;
    int tongTrongSo = 0;

    for (size_t i = 0; i < diemSo.size(); ++i) {
        tongDiemTrongTrungBinh += diemSo[i] * tronGo[i];
        tongTrongSo += tronGo[i];
    }

    return tongDiemTrongTrungBinh / tongTrongSo;
}
```

